package com.bank.cohesion.bad;

import java.math.BigDecimal;

public class GodClass {
    // Accounts + Trades + Fees + Notifications — ALL in ONE class!
    public String createAccount(String name) { return "ACC-" + name; }
    public BigDecimal getBalance(String id) { return new BigDecimal("125000"); }
    public String executeTrade(String symbol, int qty) { return "TRD-" + symbol; }
    public BigDecimal calculateFee(BigDecimal amount) {
        return amount.multiply(new BigDecimal("0.001"));
    }
    public String sendSms(String phone, String msg) { return "SMS: " + msg; }
    public String sendEmail(String email, String msg) { return "Email: " + msg; }
    public String generateReport() { return "Report generated"; }
    public boolean checkCompliance(String id) { return true; }
    // 8 methods doing 5 UNRELATED things. This is a God class.
    // "AND" test: accounts AND trades AND fees AND notifications AND compliance → LOW cohesion!
}
