// (Recommended) HIGH COHESION: only fee calculations
package com.bank.cohesion.good;

import java.math.BigDecimal;
import java.math.RoundingMode;

public class FeeCalculator {
    public BigDecimal brokerage(BigDecimal amount) {
        return amount.multiply(new BigDecimal("0.001")).setScale(2, RoundingMode.HALF_UP);
    }
    public BigDecimal gst(BigDecimal brokerage) {
        return brokerage.multiply(new BigDecimal("0.18")).setScale(2, RoundingMode.HALF_UP);
    }
    public BigDecimal totalFees(BigDecimal amount) {
        BigDecimal brk = brokerage(amount);
        return brk.add(gst(brk));
    }
    // "FeeCalculator calculates trading fees" — ONE thing → HIGH cohesion!
}
```

