// COORDINATES cohesive services — still high cohesion (orchestration is ONE responsibility)
package com.bank.cohesion.good;

import java.math.BigDecimal;

public class TradeOrchestrator {
    private final AccountService accountService;
    private final FeeCalculator feeCalculator;
    private final NotificationService notifier;

    public TradeOrchestrator(AccountService accounts, FeeCalculator fees, NotificationService notifier) {
        this.accountService = accounts;
        this.feeCalculator = fees;
        this.notifier = notifier;
    }

    public String executeTrade(String accountId, String symbol, BigDecimal amount) {
        BigDecimal balance = accountService.getBalance(accountId);
        BigDecimal fees = feeCalculator.totalFees(amount);
        notifier.sendSms(accountId, "Trade " + symbol + " Rs." + amount + " fees Rs." + fees);
        return "TRADE: " + symbol + " Rs." + amount + " fees Rs." + fees;
    }
    // "TradeOrchestrator coordinates trade execution" — orchestration is ONE thing!
}
```

```java
// ─── File: src/test/java/com/bank/cohesion/CohesionTest.java ───
package com.bank.cohesion;

import com.bank.cohesion.bad.GodClass;
import com.bank.cohesion.good.*;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import static org.assertj.core.api.Assertions.*;

class CohesionTest {

    // ═══ LOW COHESION: God class — can't test fees without loading everything ═══
    @Test
    void godClass_testFeeAlsoLoadsAccountTradeNotification() {
        GodClass god = new GodClass();
        BigDecimal fee = god.calculateFee(new BigDecimal("100000"));
        assertThat(fee).isEqualByComparingTo("100");
        // To test THIS one method, we instantiated a class that also has:
        // createAccount, executeTrade, sendSms, sendEmail, generateReport, checkCompliance
        // ALL loaded. ALL potential failure points. LOW cohesion!
    }

    // ═══ HIGH COHESION: test fees in ISOLATION ═══
    @Test
    void highCohesion_testFeesAlone() {
        FeeCalculator calc = new FeeCalculator();
        assertThat(calc.brokerage(new BigDecimal("100000"))).isEqualByComparingTo("100");
        assertThat(calc.gst(new BigDecimal("100"))).isEqualByComparingTo("18");
        assertThat(calc.totalFees(new BigDecimal("100000"))).isEqualByComparingTo("118");
        // ONLY FeeCalculator loaded. No account, no trade, no notification.
        // Clean, focused, fast test. HIGH cohesion!
    }

    // ═══ HIGH COHESION: test notifications alone ═══
    @Test
    void highCohesion_testNotificationsAlone() {
        NotificationService notifier = new NotificationService();
        assertThat(notifier.sendSms("9876543210", "Trade executed")).contains("SMS");
        // No fee calculator, no account service loaded. Focused!
    }

    // ═══ ORCHESTRATOR: coordinates cohesive services ═══
    @Test
    void orchestrator_coordinatesCohesiveServices() {
        TradeOrchestrator orchestrator = new TradeOrchestrator(
            new AccountService(), new FeeCalculator(), new NotificationService());
        String result = orchestrator.executeTrade("SAV2001", "RELIANCE", new BigDecimal("100000"));
        assertThat(result).contains("RELIANCE").contains("100000").contains("118");
    }

    // ═══ THE "AND" TEST ═══
    @Test
    void andTest_detectsLowCohesion() {
        // GodClass: "manages accounts AND executes trades AND calculates fees
        //           AND sends notifications AND checks compliance" → LOW!
        // FeeCalculator: "calculates trading fees" → HIGH!
        // AccountService: "manages bank accounts" → HIGH!
        // If your class description has "AND" → split it!
        assertThat(true).isTrue();
    }
}
```
